# Corregir la búsqueda de palabras para que sean completas y no subcadenas.
# Se usa una expresión regular que busca la palabra completa rodeada de límites de palabra (espacios, signos de puntuación, inicio/fin de cadena).
palabras_a_buscar = ['que', 'de', 'la', 'el', 'los', 'las', 'un', 'una', 'para', 'con', 'por', 'donde', 'como', 'esta', 'esto', 'hay', 'no', 'se', 'mas', 'todo']
if any(re.search(r'\b' + re.escape(palabra) + r'\b', texto.lower()) for palabra in palabras_a_buscar):
    return True # Es una orden si contiene palabras comunes del español

# Si no contiene palabras comunes del español, se considera que no es de Julio.
# Se mantiene la lógica original para avisos de máquina y textos cortos.
if texto.startswith("<"):
    return False
if any(palabra in texto.lower() for palabra in EXCLUIR_DE_ORDEN):
    return False
if texto.startswith('"') and '":' in texto:
    return False
limpio = texto.strip()
if re.match(r"^(py|json|md|sh)(?![a-zA-Z0-9])", limpio.lower()):
    return False
if re.search(r"(toca|resumen|fallo|diagnostico|aviso|confianza)\s+:", limpio):
    return False
if texto.rstrip().endswith("?"):
    return False
if len(texto.split()) < MINIMO_PALABRAS:
    return False

# Si no se cumplió ninguna de las exclusiones y tampoco se encontró una palabra común del español, se asume que no es de Julio.
return False

